True def transform(grid):
    """Repeat the sparse row-color pattern with period equal to clue count."""
    h = len(grid)
    w = len(grid[0])
    observations = {}
    for r, row in enumerate(grid):
        vals = set(row)
        if len(vals) == 1:
            color = next(iter(vals))
            if color != 0:
                observations[r] = color
    period = len(observations)
    by_residue = {}
    for r, color in observations.items():
        by_residue[r % period] = color
    return [[by_residue[r % period]] * w for r in range(h)]
